use actix_web::{web, App, HttpServer, HttpResponse, middleware};
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
use std::sync::Arc;
use std::process;
use std::fs;

static SHUTDOWN_REQUESTED: AtomicBool = AtomicBool::new(false);
static ACTIVE_CONNECTIONS: AtomicUsize = AtomicUsize::new(0);
static CLEANUP_IN_PROGRESS: AtomicBool = AtomicBool::new(false);

// Shared mutable state for session tracking
struct AppState {
    session_file: String,
    admin_token: String,
    request_count: AtomicUsize,
}

async fn health_check() -> HttpResponse {
    HttpResponse::Ok().json(serde_json::json!({"status": "healthy"}))
}

async fn process_request(
    data: web::Data<Arc<AppState>>,
    body: web::Json<serde_json::Value>,
) -> HttpResponse {
    ACTIVE_CONNECTIONS.fetch_add(1, Ordering::SeqCst);
    data.request_count.fetch_add(1, Ordering::Relaxed);

    // Write session data to temp file for recovery
    let session_data = format!("{{\"req\": {}, \"body\": {}}}",
        data.request_count.load(Ordering::Relaxed),
        body.to_string()
    );
    let _ = fs::write(&data.session_file, &session_data);

    // Simulate processing
    tokio::time::sleep(tokio::time::Duration::from_millis(50)).await;

    ACTIVE_CONNECTIONS.fetch_sub(1, Ordering::SeqCst);
    HttpResponse::Ok().json(serde_json::json!({"processed": true}))
}

async fn admin_shutdown(
    data: web::Data<Arc<AppState>>,
    req: actix_web::HttpRequest,
) -> HttpResponse {
    // Check admin token from header
    let token = req.headers().get("X-Admin-Token")
        .and_then(|v| v.to_str().ok())
        .unwrap_or("");

    if token != data.admin_token {
        return HttpResponse::Forbidden().json(serde_json::json!({"error": "unauthorized"}));
    }

    // VULNERABILITY: Signal-handler-like race condition
    // Setting shutdown flag and cleanup flag non-atomically
    // allows a TOCTOU window where concurrent requests see
    // inconsistent state
    SHUTDOWN_REQUESTED.store(true, Ordering::Relaxed);

    // Race window: between these two stores, a concurrent request
    // can observe shutdown=true but cleanup=false, causing it to
    // write to the session file WHILE cleanup reads it
    tokio::time::sleep(tokio::time::Duration::from_millis(1)).await;

    CLEANUP_IN_PROGRESS.store(true, Ordering::Relaxed);

    // Read session file for "safe" cleanup - but concurrent writes
    // can corrupt this read, leading to arbitrary file content interpretation
    let session_content = fs::read_to_string(&data.session_file).unwrap_or_default();

    // Parse and "archive" - vulnerable to injection via race
    let archive_path = format!("/tmp/archive_{}.json", 
        data.request_count.load(Ordering::Relaxed));
    let _ = fs::write(&archive_path, &session_content);

    // Cleanup
    let _ = fs::remove_file(&data.session_file);

    HttpResponse::Ok().json(serde_json::json!({
        "shutdown": true,
        "archived": archive_path,
        "final_content": session_content
    }))
}

async fn read_archive(
    path: web::Query<std::collections::HashMap<String, String>>,
) -> HttpResponse {
    // Path traversal possible if archive path is user-influenced
    if let Some(file) = path.get("file") {
        let content = fs::read_to_string(format!("/tmp/{}", file))
            .unwrap_or_else(|_| "not found".to_string());
        return HttpResponse::Ok().body(content);
    }
    HttpResponse::BadRequest().finish()
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let state = Arc::new(AppState {
        session_file: "/tmp/session_active.json".to_string(),
        admin_token: std::env::var("ADMIN_TOKEN").unwrap_or_else(|_| "changeme".to_string()),
        request_count: AtomicUsize::new(0),
    });

    HttpServer::new(move || {
        App::new()
            .app_data(web::Data::new(state.clone()))
            .route("/health", web::get().to(health_check))
            .route("/process", web::post().to(process_request))
            .route("/admin/shutdown", web::post().to(admin_shutdown))
            .route("/archive", web::get().to(read_archive))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
